sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var bases = new GlideRecord("x_1584312_bases_base");

    bases.addEncodedQuery("city=" + current.city.toString() + "^state=" + current.state.toString());
    bases.query();
    if (bases.next()) {
        current.setAbortAction(true);
        gs.addErrorMessage('The system does not accept duplicate data: City and State already exist.');
        return;
    }

    bases = new GlideRecord("x_1584312_bases_base");
    bases.addEncodedQuery("base_manager=" + current.base_manager.sys_id.toString());
    bases.query();
    if (bases.next()) {
        current.setAbortAction(true);
        gs.addErrorMessage('The system does not accept duplicate data: Base Manager already exists.');
        return; 
    }

    bases = new GlideRecord("x_1584312_bases_base");
    bases.addEncodedQuery("name=" + current.name.toString());
    bases.query();
    if (bases.next()) {
        current.setAbortAction(true);
        gs.addErrorMessage('The system does not accept duplicate data: Name already exists.');
    }

})(current, previous);
